import{_ as n,o as s,c as o,a4 as t}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0059 — Droits des abonnés : export et effacement avec le compte, lien « mes données » sans compte","description":"Extrait de docs/adr/0059-droits-des-abonnes.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0059 — Droits des abonnés : export et effacement avec le compte, lien « mes données » sans compte","description":"Extrait de docs/adr/0059-droits-des-abonnes.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0059-droits-des-abonnes.md","filePath":"developpeurs/adr/0059-droits-des-abonnes.md"}'),r={name:"developpeurs/adr/0059-droits-des-abonnes.md"};function a(i,e,c,d,l,u){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0059--droits-des-abonnés--export-et-effacement-avec-le-compte-lien--mes-données--sans-compte" tabindex="-1">ADR-0059 — Droits des abonnés : export et effacement avec le compte, lien « mes données » sans compte <a class="header-anchor" href="#adr-0059--droits-des-abonnés--export-et-effacement-avec-le-compte-lien--mes-données--sans-compte" aria-label="Permalink to &quot;ADR-0059 — Droits des abonnés : export et effacement avec le compte, lien « mes données » sans compte {#adr-0059--droits-des-abonnés--export-et-effacement-avec-le-compte-lien--mes-données--sans-compte}&quot;">​</a></h1><p><strong>Date :</strong> 28 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constats RGPD-8 (élevé) et QUAL-6 (moyen) <strong>Prolonge :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0032-droits-du-deposant-sans-compte">ADR-0032</a> (droits du déposant sans compte), dont elle reprend le patron du jeton et de l&#39;archive servie sans dépôt</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Les fiches d&#39;abonnement à la lettre d&#39;information (<code>newsletter_subscribers</code>) et aux alertes SMS (<code>sms_alert_subscribers</code>) sont tenues <strong>par adresse et par numéro</strong>, sans clé vers <code>end_users</code> : on s&#39;y abonne sans compte. L&#39;audit du 26/09 (RGPD-8) relevait deux manques :</p><ul><li>l&#39;export du compte usager (<code>app/end_users/export.py</code>) ne restituait que la lettre, et l&#39;effacement du compte (<code>app/end_users/lifecycle.py</code>) ne touchait à aucune des deux fiches : un usager qui exerçait son droit à l&#39;effacement gardait son adresse et son numéro dans deux tables que rien ne lui montrait ;</li><li>un abonné <strong>sans compte</strong> — le cas le plus fréquent — n&#39;avait aucun moyen d&#39;obtenir ses données (RGPD art. 15) autrement qu&#39;en écrivant au service.</li></ul><p>Le même audit (QUAL-6) relevait que l&#39;archive d&#39;export était compressée <strong>en mémoire</strong> (<code>io.BytesIO</code>), <strong>dans la coroutine</strong> et <strong>sans plafond</strong> : un compte chargé de pièces jointes gelait le processus pendant la compression et pouvait tenir des centaines de mégaoctets en mémoire.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Rattachement au compte par la même clé, dans la même organisation.</strong> L&#39;export et l&#39;effacement du compte incluent les fiches de lettre et d&#39;alertes SMS de son organisation qui portent <strong>la même adresse vérifiée</strong> ou <strong>le même numéro</strong>, normalisés comme les services d&#39;abonnement les écrivent (<code>normalize_email</code>, <code>normalize_phone</code>). L&#39;adresse ne vaut clé que si le compte est <strong>confirmé</strong> ; le numéro, que s&#39;il vient d&#39;une <strong>identité fédérée</strong> (revendication <code>phone_number</code>), le compte ne portant aucun numéro saisi. Une clé non prouvée pourrait être celle d&#39;un tiers. Code : <code>app/end_users/subscribers.py</code>, appelé par l&#39;export (<code>lettre_information.csv</code>, <code>alertes_sms.csv</code>) et par l&#39;effacement (<code>erase_subscriptions_of_account</code>). Une fiche vidée de toute thématique par le lien de désinscription est <strong>effacée</strong>, et non conservée vide.</li><li><strong>Lien « mes données » pour l&#39;abonné sans compte</strong>, en deux routes publiques (<code>app/api/public_subscriber_data.py</code>, <code>app/end_users/subscriber_access.py</code>) : <ul><li><code>POST /api/v1/public/subscriber-data/request?organization_id=…</code> (<code>channel</code> = <code>email</code> ou <code>sms</code>, <code>subject</code>, <code>site_id</code> facultatif, <code>captcha_token</code>) : si une fiche de l&#39;organisation porte la clé normalisée, un jeton part <strong>à cette adresse ou à ce numéro</strong>. <strong>La réponse est identique (202, même corps) que la clé soit abonnée ou non</strong>, et rien n&#39;est écrit pour une clé inconnue. Limites de débit par adresse du client (<code>RATE_LIMIT_SUBSCRIBER_DATA_PER_IP</code>, 10/1h) et par clé normalisée (<code>RATE_LIMIT_SUBSCRIBER_DATA_PER_TARGET</code>, 3/1d : chaque demande fait partir un message vers un tiers potentiel), puis captcha (<code>assert_human</code>) ;</li><li><code>POST /api/v1/public/subscriber-data/export?organization_id=…</code> (<code>token</code>) : consomme le jeton et rend une archive ZIP (<code>lettre_information.csv</code>, <code>alertes_sms.csv</code>, <code>journal_acces.csv</code>, <code>LISEZMOI.txt</code>) des seules fiches de <strong>la clé prouvée</strong> — un jeton reçu par courriel n&#39;ouvre pas les alertes SMS. <strong>404 unique</strong> pour un jeton inconnu, échu, déjà servi ou d&#39;une autre organisation. L&#39;export est journalisé (<code>EXPORT</code>) sous le périmètre de l&#39;abonné.</li></ul></li><li><strong>Le jeton suit le patron du dépôt.</strong> <code>secrets.token_urlsafe(32)</code>, remis au canal par <code>secret_context</code> (jamais recopié au journal de délivrance), stocké <strong>haché</strong> SHA-256 (<code>hash_confirmation_token</code>) dans <code>subscriber_access_tokens</code> (migration 0042), <strong>à usage unique</strong> (ligne supprimée à l&#39;ouverture), <strong>30 minutes</strong>. Une nouvelle demande remplace le lien précédent. Les liens échus sont effacés à chaque demande et par le balayage des comptes usagers.</li><li><strong>Adaptateurs inactifs = 503 explicite (ADR-0027).</strong> Le courriel part par le moteur de notifications, sur le canal SMTP du Core (<code>build_email_channel</code>) : sans <code>SMTP_HOST</code> ni <code>MAIL_FROM</code>, la demande répond <strong>503</strong> en nommant le réglage, au lieu d&#39;une acceptation sans envoi. Le Core ne livre <strong>aucun canal SMS</strong> : la demande par numéro répond 503 tant que l&#39;exploitant n&#39;a pas branché d&#39;envoi (<code>install_subscriber_sms_sender</code>). Le refus ne dépend que de la configuration, jamais de la clé.</li><li><strong>Désinscription et effacement ne sont pas dupliqués.</strong> Les routes existantes s&#39;en chargent : <code>POST /api/v1/public/newsletter/subscriptions</code> (champ <code>unsubscribe</code>) et <code>POST /api/v1/public/sms-alerts/unsubscribe</code> (<code>full</code>).</li><li><strong>Archive hors mémoire, hors boucle, plafonnée (QUAL-6).</strong> Toute archive d&#39;export (compte, demande suivie par jeton, abonné) est écrite rubrique par rubrique dans un <strong>fichier temporaire</strong> (<code>ArchiveWriter</code>), chaque écriture passant par <code>asyncio.to_thread</code>. Son contenu <strong>non compressé</strong> est plafonné par <code>RGPD_EXPORT_MAX_MB</code> (256 Mo par défaut, 1 à 4096, validé au démarrage), vérifié <strong>avant</strong> de lire chaque fichier personnel, d&#39;après sa taille déclarée. Au-delà : <strong>413</strong>, message qui renvoie au DPO, et le jeton d&#39;un abonné n&#39;est pas consommé. L&#39;archive d&#39;une demande ou d&#39;un abonné est <strong>servie en flux</strong> (<code>stream_archive</code>) puis supprimée ; celle d&#39;un compte est relue une fois pour son dépôt, puis supprimée.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><ul><li><strong>Ajouter une clé <code>end_user_id</code> aux fiches d&#39;abonnement.</strong> Rejetée : on s&#39;abonne sans compte, et un compte créé après coup devrait être rapproché de toute façon par la clé ; la correspondance par clé prouvée suffit et ne crée pas de seconde vérité.</li><li><strong>Rattacher toute adresse, confirmée ou non.</strong> Rejetée : une adresse non vérifiée peut être celle d&#39;un tiers, dont l&#39;export livrerait les abonnements et dont l&#39;effacement les supprimerait.</li><li><strong>Répondre « adresse inconnue » à la demande du lien.</strong> Rejetée : la route deviendrait un oracle d&#39;appartenance aux listes de diffusion.</li><li><strong>Accepter la demande (202) quand le canal n&#39;est pas branché.</strong> Rejetée (ADR-0027) : la personne attendrait un message qui ne partira jamais.</li><li><strong>Garder le zip en mémoire en ne le plafonnant que.</strong> Rejetée : le plafond seul n&#39;empêche pas le gel de la boucle pendant la compression, ni les centaines de mégaoctets en mémoire sous le plafond.</li></ul><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un usager retrouve dans son export, et voit effacés avec son compte, ses abonnements tenus par la même adresse vérifiée ou le même numéro.</li><li>Un abonné sans compte obtient ses données sans solliciter un agent, sans que la route ne révèle qui est abonné.</li><li>Un export volumineux ne gèle plus le processus et ne peut plus l&#39;épuiser : il est refusé clairement au-delà du plafond.</li></ul><p><strong>Négatives</strong></p><ul><li>Une table de plus (<code>subscriber_access_tokens</code>) et une migration (0042) ; la ligne garde la clé en clair le temps du jeton, comme les fiches qu&#39;elle ouvre.</li><li>Le lien par SMS n&#39;existe qu&#39;une fois un envoi branché par l&#39;exploitant ; jusque-là, la demande par numéro répond 503 et la personne s&#39;adresse au service.</li><li>Le chemin <code>/mes-donnees</code> du lien envoyé par courriel est <strong>supposé</strong> : un site public qui en retient un autre doit adapter le texte (<code>SUBSCRIBER_DATA_LINK_TEXTS</code>).</li><li>L&#39;archive transite par le répertoire temporaire du système le temps de la requête : sur une instance où ce répertoire est partagé, l&#39;exploitant doit le restreindre au processus de l&#39;API (les fichiers sont créés en droits restreints par <code>mkstemp</code>).</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Export et effacement du compte étendus aux fiches de lettre et d&#39;alertes SMS (<code>app/end_users/subscribers.py</code>). Preuve : <code>tests/test_abonnements_du_compte.py</code>.</li><li>[x] Routes « mes données » d&#39;un abonné sans compte, jeton haché à usage unique, 503 si canal inactif. Preuve : <code>tests/test_droits_des_abonnes.py</code>.</li><li>[x] Archive dans un fichier temporaire, hors boucle, plafonnée (<code>RGPD_EXPORT_MAX_MB</code>), servie en flux. Preuve : <code>test_l_archive_est_compressee_hors_de_la_boucle_d_evenements</code>, <code>test_une_archive_au_dela_du_plafond_est_refusee_en_413</code>, <code>test_l_archive_passe_par_un_temporaire_supprime_apres_le_flux</code>.</li><li>[x] Notice : §7.9 (paragraphe pour qui réalise le site public).</li><li>[ ] Brancher un envoi SMS du lien « mes données » quand une passerelle SMS sera retenue.</li><li>[ ] Page <code>/mes-donnees</code> du site public de référence (saisie de l&#39;adresse ou du numéro, puis ouverture du lien).</li></ul>',17)])])}const g=n(r,[["render",a]]);export{m as __pageData,g as default};
